insert into emission_factors (id, category, unit, value, output_unit, region, scope, source, source_url, publication, effective_year, version, notes, uncertainty, needs_validation)
values ('IN-ELEC-GRID-2026', 'electricity.grid', 'kWh', 0.727, 'kgCO2e', 'IN', 'scope2', 'Central Electricity Authority (CEA), India', 'https://cea.nic.in/cdm-co2-baseline-database/', 'CO2 Baseline Database for the Indian Power Sector, User Guide v20.0 (FY 2023-24 weighted-average emission factor adjusted for renewables)', 2024, 1, null, 'All-India grid-average factor; CEA republishes this annually (newer v22.0, FY 2025-26, already supersedes v20.0) and the figure shifts with the generation mix. Re-verification found the "weighted average, adjusted for renewables" variant reported at 0.727 tCO2/MWh for FY2023-24 (previously this entry held 0.79 — corrected). CEA also separately publishes a higher "Combined Margin" figure (~0.757) used for different accounting purposes (e.g. CDM baselines) — confirm which variant Ecoverse intends before production, and re-check both against the primary CEA PDF, which this pass could not fetch directly.', true);

insert into emission_factors (id, category, unit, value, output_unit, region, scope, source, source_url, publication, effective_year, version, notes, uncertainty, needs_validation)
values ('GLOBAL-LPG-2026', 'cooking.lpg', 'kg', 2.98, 'kgCO2e', 'GLOBAL', 'scope1', 'IPCC', 'https://www.ipcc-nggip.iges.or.jp/public/2006gl/', '2006 IPCC Guidelines for National Greenhouse Gas Inventories, Vol. 2, Table 1.4', 2006, 1, null, 'IPCC default combustion factor; relatively stable across LPG blends. The underlying 63.1 kgCO2/GJ (NCV basis) default this is derived from was corroborated against a secondary reproduction of the IPCC 2006 table during re-verification.', true);

