values ('GLOBAL-PNG-2026', 'cooking.png', 'm3', 2.15, 'kgCO2e', 'GLOBAL', 'scope1', 'IPCC', 'https://www.ipcc-nggip.iges.or.jp/public/2006gl/', '2006 IPCC Guidelines for National Greenhouse Gas Inventories, Vol. 2, Table 1.4 (natural gas default, converted using an assumed calorific value)', 2006, 1, null, 'Derived using an assumed piped-gas calorific value (~38-39 MJ/m3); actual local gas composition changes this. Confirm against the gas distributor''s published calorific value before production use.', true);

insert into emission_factors (id, category, unit, value, output_unit, region, scope, source, source_url, publication, effective_year, version, notes, uncertainty, needs_validation)
values ('GLOBAL-PETROL-2026', 'transport.fuel.petrol', 'L', 2.31, 'kgCO2e', 'GLOBAL', 'scope1', 'IPCC', 'https://www.ipcc-nggip.iges.or.jp/public/2006gl/', '2006 IPCC Guidelines for National Greenhouse Gas Inventories, Vol. 2, Table 3.2.1 (motor gasoline default)', 2006, 1, null, 'IPCC default combustion factor, CO2 only (excludes CH4/N2O). Applies per liter regardless of vehicle type (car, two-wheeler, etc). The underlying 69.3 kgCO2/GJ default is a well-known, frequently-cited IPCC 2006 figure; re-verification could not re-fetch the primary PDF table this pass to confirm it directly — do so before production.', true);

insert into emission_factors (id, category, unit, value, output_unit, region, scope, source, source_url, publication, effective_year, version, notes, uncertainty, needs_validation)
values ('GLOBAL-DIESEL-2026', 'transport.fuel.diesel', 'L', 2.68, 'kgCO2e', 'GLOBAL', 'scope1', 'IPCC', 'https://www.ipcc-nggip.iges.or.jp/public/2006gl/', '2006 IPCC Guidelines for National Greenhouse Gas Inventories, Vol. 2, Table 3.2.1 (diesel/gas oil default)', 2006, 1, null, 'IPCC default combustion factor, CO2 only. Applies per liter regardless of vehicle type. The underlying 74.1 kgCO2/GJ default is a well-known, frequently-cited IPCC 2006 figure; re-verification could not re-fetch the primary PDF table this pass to confirm it directly — do so before production.', true);

insert into emission_factors (id, category, unit, value, output_unit, region, scope, source, source_url, publication, effective_year, version, notes, uncertainty, needs_validation)
values ('GLOBAL-STATIONARY-DIESEL-2026', 'stationary.fuel.diesel', 'L', 2.68, 'kgCO2e', 'GLOBAL', 'scope1', 'IPCC', 'https://www.ipcc-nggip.iges.or.jp/public/2006gl/', '2006 IPCC Guidelines for National Greenhouse Gas Inventories, Vol. 2, Table 2.2 (stationary combustion, diesel/gas oil default). Same numeric CO2 factor as the mobile-combustion default (Table 3.2.1) — IPCC''s Tier 1 default CO2 factors are fuel-based, not technology-based; only the CH4/N2O defaults differ by equipment type, and those aren''t included here.', 2006, 1, null, 'For backup generators / stationary equipment, not vehicles. CO2 only.', true);

