values ('GLOBAL-CNG-2026', 'transport.fuel.cng', 'kg', 2.53, 'kgCO2e', 'GLOBAL', 'scope1', 'IPCC (derived)', 'https://www.ipcc-nggip.iges.or.jp/public/2006gl/', '2006 IPCC Guidelines for National Greenhouse Gas Inventories, Vol. 2, Table 3.2.1 (natural gas default, converted to a per-kg CNG basis)', 2006, 1, null, 'Lower confidence than the petrol/diesel factors above — the per-kg conversion depends on assumed CNG density and calorific value. Validate before production use.', true);

insert into emission_factors (id, category, unit, value, output_unit, region, scope, source, source_url, publication, effective_year, version, notes, uncertainty, needs_validation)
values ('GLOBAL-BUS-2026', 'transport.public.bus', 'passenger-km', 0.105, 'kgCO2e', 'GLOBAL', 'scope3', 'UK DEFRA/DESNZ', 'https://www.gov.uk/government/collections/government-conversion-factors-for-company-reporting', 'UK Government GHG Conversion Factors for Company Reporting (average local bus, per passenger-km)', 2024, 1, null, 'UK average-occupancy figure used as a global fallback; actual value depends heavily on vehicle type, route, and occupancy. No India-specific public dataset identified yet — validate before production use. Re-verification corroborated this against a secondary source citing ~0.102 for the 2024 DEFRA/DESNZ average local bus factor — close match.', true);

insert into emission_factors (id, category, unit, value, output_unit, region, scope, source, source_url, publication, effective_year, version, notes, uncertainty, needs_validation)
values ('GLOBAL-RAIL-2026', 'transport.public.rail', 'passenger-km', 0.035, 'kgCO2e', 'GLOBAL', 'scope3', 'UK DEFRA/DESNZ', 'https://www.gov.uk/government/collections/government-conversion-factors-for-company-reporting', 'UK Government GHG Conversion Factors for Company Reporting (national rail, per passenger-km)', 2024, 1, null, 'UK average figure used as a global fallback pending an Indian Railways-specific factor. Electrified-vs-diesel traction mix materially changes this — validate before production use. Re-verification corroborated this exactly against a secondary source citing 0.035 for the 2024 DEFRA/DESNZ national rail factor.', true);

insert into emission_factors (id, category, unit, value, output_unit, region, scope, source, source_url, publication, effective_year, version, notes, uncertainty, needs_validation)
values ('GLOBAL-AIR-DOMESTIC-2026', 'transport.air.domestic', 'passenger-km', 0.158, 'kgCO2e', 'GLOBAL', 'scope3', 'UK DEFRA/DESNZ', 'https://www.gov.uk/government/collections/government-conversion-factors-for-company-reporting', 'UK Government GHG Conversion Factors for Company Reporting (domestic flight, average passenger, per passenger-km)', 2024, 1, null, 'Short-haul domestic average; varies with aircraft load factor and sector length. This figure is deliberately the CO2-only basis, excluding DEFRA/DESNZ''s optional radiative-forcing (RF) uplift for non-CO2 aviation warming effects (contrails, NOx-induced ozone) — DEFRA''s own headline "with RF" domestic figure runs noticeably higher (secondary sources put recent editions around 0.23-0.27 with RF vs. the ~0.14-0.16 without-RF range this entry sits in). Whether Ecoverse should report CO2-only or RF-inclusive aviation emissions is a methodology choice for the carbon-accounting reviewer to confirm, not just a factual correction — validate before production use.', true);

insert into emission_factors (id, category, unit, value, output_unit, region, scope, source, source_url, publication, effective_year, version, notes, uncertainty, needs_validation)
values ('GLOBAL-AIR-INTL-2026', 'transport.air.international', 'passenger-km', 0.148, 'kgCO2e', 'GLOBAL', 'scope3', 'UK DEFRA/DESNZ', 'https://www.gov.uk/government/collections/government-conversion-factors-for-company-reporting', 'UK Government GHG Conversion Factors for Company Reporting (long-haul international flight, average passenger, per passenger-km)', 2024, 1, null, 'CO2-only figure (excludes non-CO2 radiative forcing effects of aviation at altitude, which some methodologies include via a multiplier). Same basis caveat as the domestic-flight entry above — see its note for the with-RF vs. without-RF gap found during re-verification. Validate methodology choice before production use.', true);

insert into emission_factors (id, category, unit, value, output_unit, region, scope, source, source_url, publication, effective_year, version, notes, uncertainty, needs_validation)
values ('GLOBAL-WASTE-LANDFILL-2026', 'waste.landfill.mixed', 'kg', 0.5, 'kgCO2e', 'GLOBAL', 'scope3', 'UK DEFRA/DESNZ', 'https://www.gov.uk/government/collections/government-conversion-factors-for-company-reporting', 'UK Government GHG Conversion Factors for Company Reporting (waste disposal, household residual waste to landfill, per kg)', 2024, 1, null, 'Re-verification correction: this entry previously cited "2006 IPCC Guidelines Vol. 5, Waste" as its source, but that volume does not publish a single flat default factor for mixed waste to landfill — it specifies a first-order-decay model requiring site-specific inputs (degradable organic carbon, methane correction factor, etc.), not a table lookup. Re-sourced to DEFRA/DESNZ''s published household-residual-waste-to-landfill factor (~0.497-0.5 kgCO2e/kg in recent editions), which is a genuine table value and closely matched this entry''s existing number. Still highly dependent on waste composition, landfill management practice, and methane capture — a locally-specific factor is strongly recommended before production use, and "household residual" may not represent business/campus/event mixed waste streams well.', true);

insert into emission_factors (id, category, unit, value, output_unit, region, scope, source, source_url, publication, effective_year, version, notes, uncertainty, needs_validation)
values ('GLOBAL-DIET-VEGAN-2026', 'food.diet.vegan', 'day', 2.89, 'kgCO2e', 'GLOBAL', 'scope3', 'Scarborough et al. 2014', 'https://doi.org/10.1007/s10584-014-1169-1', '"Dietary greenhouse gas emissions of meat-eaters, fish-eaters, vegetarians and vegans in the UK", Climatic Change (2014)', 2014, 1, null, 'UK-population dietary study, used here as a simplified diet-type proxy. Not India-specific — Indian dietary patterns and food-system emissions differ materially. Treat as illustrative only until replaced with regionally-appropriate data. Re-verification corroborated this against secondary summaries of the paper (consistently describing vegan diets at "almost 3 kg CO2e/day") but could not re-fetch the primary paper''s table to confirm the exact figure directly.', true);

