insert into emission_factors (id, category, unit, value, output_unit, region, scope, source, source_url, publication, effective_year, version, notes, uncertainty, needs_validation)
values ('GLOBAL-DIET-HIGH-MEAT-2026', 'food.diet.highMeat', 'day', 7.19, 'kgCO2e', 'GLOBAL', 'scope3', 'Scarborough et al. 2014', 'https://doi.org/10.1007/s10584-014-1169-1', '"Dietary greenhouse gas emissions of meat-eaters, fish-eaters, vegetarians and vegans in the UK", Climatic Change (2014)', 2014, 1, null, 'Same UK-study caveat as the vegan diet factor above. "High meat" = above-average meat consumption (>100g/day) in the source study. Re-verification corroborated this against secondary summaries consistently describing high-meat diets at "over 7 kg CO2e/day".', true);

